#!/usr/bin/env bash
set -euo pipefail
WS="/home/kavia/workspace/code-generation/personal-task-manager-262972-262981/to_do_app_native"
command -v sudo >/dev/null || { echo 'sudo required' >&2; exit 2; }
PKGS=(cmake pkg-config libx11-dev libgtk-4-dev libsqlite3-dev)
[ "${DEBUG:-}" = "true" ] && PKGS+=(gdb)
TO_INSTALL=()
for p in "${PKGS[@]}"; do dpkg-query -W -f='${Status}' "$p" 2>/dev/null | grep -q "install ok installed" || TO_INSTALL+=("$p"); done
if [ ${#TO_INSTALL[@]} -ne 0 ]; then tries=0; until sudo apt-get update -q && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends -qq "${TO_INSTALL[@]}"; do tries=$((tries+1)); [ "$tries" -ge 3 ] && { echo 'apt install failed' >&2; exit 3; }; sleep 2; done; fi
command -v cmake >/dev/null || { echo 'cmake not available' >&2; exit 4; }
command -v ctest >/dev/null || { echo 'ctest not available' >&2; exit 5; }
CATCH_DIR="/usr/local/include/catch2"; CATCH_HDR="$CATCH_DIR/catch.hpp"
if [ ! -f "$CATCH_HDR" ]; then sudo mkdir -p "$CATCH_DIR"; TMP=$(mktemp); URL=https://raw.githubusercontent.com/catchorg/Catch2/v2.13.10/single_include/catch2/catch.hpp; tries=0; until curl -sSL -o "$TMP" "$URL"; do tries=$((tries+1)); [ "$tries" -ge 3 ] && { echo 'failed to download Catch2' >&2; rm -f "$TMP"; exit 6; }; sleep 1; done; if ! grep -q "CATCH_CONFIG_MAIN\|CATCH_CONFIG_RUNNER" "$TMP"; then echo 'catch header missing expected token' >&2; rm -f "$TMP"; exit 7; fi; sudo mv "$TMP" "$CATCH_HDR"; fi
# final validation
command -v cmake >/dev/null || { echo 'cmake not on PATH after install' >&2; exit 8; }
command -v ctest >/dev/null || { echo 'ctest not on PATH after install' >&2; exit 9; }

#!/usr/bin/env bash
set -euo pipefail
WS="/home/kavia/workspace/code-generation/personal-task-manager-262972-262981/to_do_app_native"
mkdir -p "$WS/src" "$WS/build" "$WS/cmake" "$WS/logs" && cd "$WS"
cat > "$WS/src/main.cpp" <<'CPP'
#include <gtk/gtk.h>
static void on_activate(GApplication *app, gpointer user_data){
  GtkWidget *win = gtk_application_window_new(GTK_APPLICATION(app));
  gtk_window_set_title(GTK_WINDOW(win), "ToDo - Scaffold");
  gtk_window_set_default_size(GTK_WINDOW(win), 480, 240);
  gtk_widget_show(win);
}
int main(int argc, char **argv){
  GtkApplication *app = gtk_application_new("org.example.ToDo", G_APPLICATION_FLAGS_NONE);
  g_signal_connect(app, "activate", G_CALLBACK(on_activate), NULL);
  int status = g_application_run(G_APPLICATION(app), argc, argv);
  g_object_unref(app);
  return status;
}
CPP
cat > "$WS/CMakeLists.txt" <<'CM'
cmake_minimum_required(VERSION 3.16)
project(to_do_app_native LANGUAGES CXX)
find_package(PkgConfig REQUIRED)
pkg_check_modules(GTK4 REQUIRED IMPORTED_TARGET gtk4)
add_executable(to_do_app_native src/main.cpp)
if(TARGET PkgConfig::GTK4)
  target_link_libraries(to_do_app_native PRIVATE PkgConfig::GTK4)
else()
  if(GTK4_FOUND)
    target_include_directories(to_do_app_native PRIVATE ${GTK4_INCLUDE_DIRS})
    target_link_libraries(to_do_app_native PRIVATE ${GTK4_LIBRARIES})
    if(GTK4_CFLAGS_OTHER)
      target_compile_options(to_do_app_native PRIVATE ${GTK4_CFLAGS_OTHER})
    endif()
  else()
    message(FATAL_ERROR "GTK4 pkg-config not found; install libgtk-4-dev")
  endif()
endif()
if(EXISTS "${CMAKE_SOURCE_DIR}/cmake/tests.cmake")
  include(${CMAKE_SOURCE_DIR}/cmake/tests.cmake)
endif()
CM
