cmake -S "$WS" -B . -DCMAKE_BUILD_TYPE=Debug || { echo 'cmake configure failed' >&2; exit 3; }
cmake --build . -- -j"$(nproc)" || { echo 'build failed' >&2; exit 4; }
SH
chmod +x "$WS/build.sh"; fi
