export DISPLAY=${DISPLAY:-:99}
"$WS/start-wrapper.sh"
PIDFILE="$WS/.app_pid"
for i in $(seq 1 30); do if [ -f "$PIDFILE" ]; then break; fi; sleep 1; done
[ -f "$PIDFILE" ] || { echo 'app failed to start (no pid file)' >&2; exit 3; }
APP_PID=$(cat "$PIDFILE")
if ! ps -p "$APP_PID" >/dev/null 2>&1; then echo 'app pid not running' >&2; exit 4; fi
echo "started_pid=$APP_PID" > "$WS/logs/start_check.txt"
